def comps_of(I):
    seen=[[False]*len(r) for r in I]; out=[]
    H=len(I)
    for i in range(H):
        for j in range(len(I[0])):
            if I[i][j] and not seen[i][j]:
                col=I[i][j]; stack=[(i,j)]; seen[i][j]=True; comp=[]
                while stack:
                    r,c=stack.pop(); comp.append((r,c))
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            nr,nc=r+dr,c+dc
                            if 0<=nr<H and 0<=nc<len(I[0]) and I[nr][nc]==col and not seen[nr][nc]:
                                seen[nr][nc]=True; stack.append((nr,nc))
                out.append((col,comp))
    return out
