    return [c for c in range(W) if all(I[r][c]==4 for r in range(H))]

def f(I, placement='orig', barlen_mode='size'):
    H,W=len(I),len(I[0])
    sc=sep_cols(I)
    res=[]
    for col,cells in comps_of(I):
        if col==4: continue
        rs=[p[0] for p in cells]; cls=[p[1] for p in cells]
        r0,c0=min(rs),min(cls)
        L=max(rs)-min(rs)+1  # default
        if len(cells)>1:
            if barlen_mode=='size': L=len(cells)
            if L==2:
                pass
            bar=[(r0+k,c0) for k in range(L)]
        else:
            bar=[cells[0]]
        rr=r0 if placement=='orig' else r0+1
        res.append((rr,[c for r,c in bar]))
    out=[[0]*W for _ in I]
    for rr,cl in res:
        for idx,c in enumerate(cl):
            if rr<len(out) and 0<=c<W:
                out[rr][c]=col
    pts=[(col,cells[0]) for col,cells in comps_of(I) if len(cells)==1 and col!=4]
    for col,(r,c) in pts:
        out[r][c]=col
    return out

